package runcontrol

import (
	"context"
	"database/sql"
	"path/filepath"
	"testing"
	"time"
)

// Proves: timestamps stored as RFC3339Nano TEXT (formatTime trims trailing
// fractional zeros) do not order chronologically under SQLite BINARY collation.
func TestGauntletRFC3339NanoTextOrderingInvertsSubSecondNeighbors(t *testing.T) {
	dir := t.TempDir()
	db, err := sql.Open("sqlite", filepath.Join(dir, "order.db"))
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.ExecContext(context.Background(), `CREATE TABLE runs (run_id TEXT PRIMARY KEY, updated_at TEXT NOT NULL)`); err != nil {
		t.Fatal(err)
	}
	earlier := time.Date(2026, 8, 25, 10, 0, 5, 0, time.UTC)        // chronologically older
	later := time.Date(2026, 8, 25, 10, 0, 5, 100000000, time.UTC) // +100ms, newer
	olderText, newerText := formatTime(earlier), formatTime(later)
	if olderText == newerText {
		t.Fatalf("expected different encodings")
	}
	for _, row := range []struct{ id, at string }{{"run_old", olderText}, {"run_new", newerText}} {
		if _, err := db.ExecContext(context.Background(), `INSERT INTO runs (run_id, updated_at) VALUES (?, ?)`, row.id, row.at); err != nil {
			t.Fatal(err)
		}
	}
	var first string
	if err := db.QueryRowContext(context.Background(), `SELECT run_id FROM runs ORDER BY updated_at DESC LIMIT 1`).Scan(&first); err != nil {
		t.Fatal(err)
	}
	if first == "run_new" {
		t.Fatalf("expected DESC ordering to return the chronologically newer row first under equal-prefix fractions")
	}
	t.Logf("encodings: older=%q newer=%q; DESC returned %q first (chronologically inverted)", olderText, newerText, first)

	var count int
	if err := db.QueryRowContext(context.Background(), `SELECT COUNT(*) FROM runs WHERE updated_at < ?`, newerText).Scan(&count); err != nil {
		t.Fatal(err)
	}
	if count != 0 {
		t.Fatalf("keyset predicate: expected collation-consistent exclusion, got %d", count)
	}
}

